def _load_embedded_names():
    compressed = base64.b64decode("".join(NAME_CHUNKS).encode("ascii"))
    raw = gzip.decompress(compressed)
    nm = json.loads(raw.decode("utf-8"))
    # 去除中文注释：去掉 [中文] 后缀，纯中文条目回退到 key
    import re
    clean = {}
    for k, v in nm.items():
        # 去掉末尾的 [中文] 部分
        v2 = re.sub(r'\s*\[[^\[\]]*\][\s]*$', '', v).strip()
        # 检查是否只剩下中文（或空）
        if v2 and not re.search(r'[a-zA-Z]', v2):
            # 纯中文/空 → 用 key 作为英文名
            clean[k] = k
        else:
            clean[k] = v2 if v2 else k
    return clean

