def _load_embedded_db():
    """解压并加载内嵌数据库"""
    compressed = base64.b64decode("".join(EMBEDDED_CHUNKS).encode("ascii"))
    raw = gzip.decompress(compressed)
    return json.loads(raw.decode("utf-8"))


# ══════════════════════════════════════════════════════
# V3 Slot Preset 扫描（争夺区等新系统）
# ══════════════════════════════════════════════════════

def add_v3_slot_data(db, slot_map, item_tags, RECORDS, load_json):
    """扫描 v3slotpreset_*.json，将 V3 物品关联写入 slot_map
    
    db: 可选的 DB dict（从内嵌加载后使用），为 None 时从 item_tags 构建
    slot_map: region -> set(container_names) 的字典
    item_tags: item_tags 字典
    RECORDS: records 目录路径
    load_json: JSON 加载函数
    """
    # 建立实体名→UUID 索引
    v3_entity_to_uuid = {}
    for uid, info in item_tags.items():
        ename = info.get("n", "").replace("EntityClassDefinition.", "")
        if ename:
            v3_entity_to_uuid[ename] = uid
    
    v3_items = {}  # uuid -> set(regions)
    v3_slot_dir = os.path.join(RECORDS, "harvestable", "slotpresets")
    
    # 建文件索引
    file_idx = {}
    for root, dirs, files in os.walk(RECORDS):
        for f in files:
            if f.endswith(".json"):
                file_idx[f] = os.path.join(root, f)
    
    def _v3_entity_name(ref):
        name = os.path.basename(ref.replace("\\", "/").replace("file://./", ""))
        return name.replace(".json", "")
    
    def _v3_filename(ref):
        return os.path.basename(ref.replace("file://./", "").replace("/", os.sep))
    
    print("  解析 V3 slotpreset...")
    # 先处理 v3slotpreset_*.json（标准 V3 格式）
    for fname in sorted(os.listdir(v3_slot_dir)):
        if not fname.startswith("v3slotpreset_") or not fname.endswith(".json"):
            continue
        region = fname.replace("v3slotpreset_", "").replace(".json", "")
        data = load_json(os.path.join(v3_slot_dir, fname))
        if not data:
            continue
        mc = data.get("_RecordValue_", {}).get("multiConfig", {})
        tagged = mc.get("taggedConfigs", [])
        if not tagged:
            continue
        
        refs = set()
        for tc in tagged:
            sref = tc.get("subConfig", {}).get("subConfigRef", "")
            if sref:
                refs.add(sref)
        
        for ref in refs:
            ref_fn = _v3_filename(ref)
            shc_path = file_idx.get(ref_fn)
            if not shc_path:
                shc_dir = os.path.join(RECORDS, "harvestable", "subharvestableconfigs")
                sp = os.path.join(shc_dir, ref_fn)
                if os.path.exists(sp):
                    shc_path = sp
            if not shc_path:
                continue
            
            shc = load_json(shc_path)
            if not shc:
                continue
            
            sub = shc.get("_RecordValue_", {}).get("subConfig", {})
            slots = sub.get("subHarvestables", [])
            base_chance = sub.get("initialSlotsProbability", 1.0)
            
            v3_items = _resolve_subharvestables(slots, region, v3_items, v3_entity_to_uuid, file_idx, load_json, _v3_entity_name, _v3_filename, base_chance)

    # 处理 lootgeneration_slotpreset_*.json（多配置容器，如 StormBreaker）
    for fname in sorted(os.listdir(v3_slot_dir)):
        if not fname.startswith("lootgeneration_slotpreset_") or not fname.endswith(".json"):
            continue
        region = fname.replace("lootgeneration_slotpreset_", "").replace(".json", "")
        data = load_json(os.path.join(v3_slot_dir, fname))
        if not data:
            continue
        mc = data.get("_RecordValue_", {}).get("multiConfig", {})
        tagged = mc.get("taggedConfigs", [])
        if not tagged:
            continue
        
        for tc in tagged:
            sub_cfg = tc.get("subConfig", {})
            # 支持两种格式：subConfigRef（独立文件）和 subConfigManual（内联配置）
            if sub_cfg.get("subConfigRef"):
                ref_fn = _v3_filename(sub_cfg["subConfigRef"])
                shc_path = file_idx.get(ref_fn)
                if not shc_path:
                    shc_dir = os.path.join(RECORDS, "harvestable", "subharvestableconfigs")
                    sp = os.path.join(shc_dir, ref_fn)
                    if os.path.exists(sp):
                        shc_path = sp
                if shc_path:
                    shc = load_json(shc_path)
                    if shc:
                        sub = shc.get("_RecordValue_", {}).get("subConfig", {})
                        slots = sub.get("subHarvestables", [])
                        base_chance = sub.get("initialSlotsProbability", 1.0)
                        v3_items = _resolve_subharvestables(slots, region, v3_items, v3_entity_to_uuid, file_idx, load_json, _v3_entity_name, _v3_filename, base_chance)
            elif sub_cfg.get("subConfigManual"):
                manual = sub_cfg["subConfigManual"]
                slots = manual.get("subHarvestables", [])
                base_chance = manual.get("initialSlotsProbability", 1.0)
                v3_items = _resolve_subharvestables(slots, region, v3_items, v3_entity_to_uuid, file_idx, load_json, _v3_entity_name, _v3_filename, base_chance)
    
    # 写入 slot_map
    for uid, info in v3_items.items():
        for r, meta in info.get("regions", []):
            if r not in slot_map:
                slot_map[r] = []
            # 查重：同一个uid在同一个region下只存一次，合并meta
            existing = next((x for x in slot_map[r] if isinstance(x, dict) and x.get("n") == f"__v3__{uid}"), None)
            if existing:
                # 合并 meta（取更精确的 chance/min/max）
                if meta.get("chance") is not None:
                    existing["chance"] = min(existing.get("chance", 1.0), meta["chance"])
                if meta.get("min") is not None:
                    existing["min"] = min(existing.get("min", 1), meta["min"])
                if meta.get("max") is not None:
                    existing["max"] = max(existing.get("max", 1), meta["max"])
            else:
                slot_map[r].append({"n": f"__v3__{uid}", **meta})
    
    print(f"   找到 {len(v3_items)} 个 V3 物品关联")
    return slot_map


def _resolve_subharvestables(slots, region, v3_items, v3_entity_to_uuid, file_idx, load_json, _v3_entity_name, _v3_filename, base_chance=1.0):
    """从 subHarvestables 列表中解析物品 UUID，捕获 chanceToSpawn/min/max"""
    # base_chance 来自 SubHarvestableConfig.initialSlotsProbability
    for sobj in slots:
        # 捕获相对概率
        rel_prob = sobj.get("relativeProbability", 1.0)
        # 捕获 lootConfig 中的 chanceToGenerate
        lc = sobj.get("lootConfig", {})
        lc_chance = lc.get("chanceToGenerate", 1.0) if isinstance(lc, dict) else 1.0
        final_chance = base_chance * rel_prob * lc_chance
        
        # 捕获 min/max count（来自 lootConstraints 的 totalResultsLimit 或 entries 数量）
        lc_con = lc.get("lootConstraints", {}) if isinstance(lc, dict) else {}
        total_limit = lc_con.get("totalResultsLimit", 1) if isinstance(lc_con, dict) else 1
        
        hec = sobj.get("harvestableEntityClass", "")
        if hec:
            ecn = _v3_entity_name(hec)
            if ecn:
                if ecn in v3_entity_to_uuid:
                    uid = v3_entity_to_uuid[ecn]
                    v3_items.setdefault(uid, {"regions": []})["regions"].append(
                        (region, {"chance": final_chance, "min": 1, "max": total_limit}))
                    continue
                # 否则是容器，查 loadout
                ent_path = file_idx.get(ecn + ".json")
                if ent_path:
                    ent = load_json(ent_path)
                    if ent:
                        rv = ent.get("_RecordValue_", {})
                        for comp in rv.get("Components", []):
                            if comp.get("_Type_") == "SEntityComponentDefaultLoadoutParams":
                                entries = comp.get("loadout", {}).get("entries", [])
                                for entry in entries:
                                    eref = entry.get("entityClassReference", "") or entry.get("entityClassName", "")
                                    if not eref:
                                        continue
                                    item_name = _v3_entity_name(eref)
                                    if item_name in v3_entity_to_uuid:
                                        uid = v3_entity_to_uuid[item_name]
                                        v3_items.setdefault(uid, {"regions": []})["regions"].append(
                                            (region, {"chance": final_chance, "min": 1, "max": total_limit}))
        
        # 如果是 harvestable preset（实体引用），解析 entityClass 的 loadout
        h = sobj.get("harvestable", "")
        if h:
            hp_fn = _v3_filename(h)
            hp_path = file_idx.get(hp_fn)
            if hp_path:
                hp = load_json(hp_path)
                if hp:
                    ec_ref = hp.get("_RecordValue_", {}).get("entityClass", "")
                    if ec_ref:
                        ecn = _v3_entity_name(ec_ref)
                        ent_path = file_idx.get(ecn + ".json")
                        if ent_path:
                            ent = load_json(ent_path)
                            if ent:
                                rv = ent.get("_RecordValue_", {})
                                for comp in rv.get("Components", []):
                                    if comp.get("_Type_") == "SEntityComponentDefaultLoadoutParams":
                                        entries = comp.get("loadout", {}).get("entries", [])
                                        for entry in entries:
                                            eref = entry.get("entityClassReference", "") or entry.get("entityClassName", "")
                                            if not eref:
                                                continue
                                            item_name = _v3_entity_name(eref)
                                            if item_name in v3_entity_to_uuid:
                                                uid = v3_entity_to_uuid[item_name]
                                                v3_items.setdefault(uid, {"regions": []})["regions"].append(
                                                    (region, {"chance": final_chance, "min": 1, "max": total_limit}))
    return v3_items


# ══════════════════════════════════════════════════════
# 数据打包（仅首次或重建时使用）
# ══════════════════════════════════════════════════════

def build_database():
    """从原始 JSON 打包为 loot_db.json"""
    print("📦 正在解包掉落数据...")
    
    # 1. 标签
    print("  加载标签库...")
    with open(TAG_DB, "r", encoding="utf-8") as f:
        td = json.load(f)
    tag_map = {}
    def _walk(tl, ps):
        for t in tl:
            uid = get_uuid(t)
            tag_map[uid] = " → ".join(ps + [t.get("tagName", "?")])
            _walk(t.get("children", []), ps + [t.get("tagName", "?")])
    _walk(td["_RecordValue_"]["tags"], [])
    
    # 2. 物品 -> 标签（含层级展开：A->B->C 同时拥有 A->B 和 A）
    print("  扫描物品实体...")
    # 建立 tag_name → full_path 的辅助索引（用于生成组件合成标签）
    _tag_path_by_name = {}  # 不区分大小写，小写 → path
    _tag_path_exact = {}    # 精确匹配，用于 Size0/Size1 等
    for _uid, _path in tag_map.items():
        _parts = _path.split(" \u2192 ")
        _leaf = _parts[-1]
        _leaf_lower = _leaf.lower()
        if _leaf_lower not in _tag_path_by_name:
            _tag_path_by_name[_leaf_lower] = _path
        _tag_path_exact[_leaf] = _path
    
    _grade_map = {1: "A", 2: "B", 3: "C", 4: "D", 5: "E"}
    
    item_tags = {}
    for root, dirs, files in os.walk(os.path.join(RECORDS, "entities")):
        for fname in files:
            if not fname.endswith(".json"): continue
            data = load_json(os.path.join(root, fname))
            if not data: continue
            uid = get_uuid(data)
            if not uid: continue
            tags = set()
            item_name = data.get("_RecordName_", short_name(fname))
            is_mag = "_mag" in item_name.lower() or "_mag" in fname.lower()
            # 扫描实体自身 tags 字段
            for t in data.get("_RecordValue_", {}).get("tags", []):
                tid = get_uuid(t)
                if tid and tid in tag_map:
                    full = tag_map[tid]
                    tags.add(full)
                    if is_mag:
                        parts = full.split(" \u2192 ")
                        for i in range(1, len(parts)):
                            tags.add(" \u2192 ".join(parts[:i]))
            # 检查是否缺少与掉落/组件相关的标签
            has_loot_tags = any("LootGeneration" in t or "Ship → Components" in t for t in tags)
            if not has_loot_tags:
                # 尝试从 AttachDef 生成合成标签
                comps = data.get("_RecordValue_", {}).get("Components", [])
                if comps and isinstance(comps, list):
                    for c in comps:
                        if not isinstance(c, dict): continue
                        if "SAttachableComponentParams" in c.get("_Type_", ""):
                            ad = c.get("AttachDef", {})
                            comp_type = ad.get("Type", "")
                            comp_size = ad.get("Size", -1)
                            comp_grade = ad.get("Grade", -1)
                            # 尝试匹配 Ship → Components → {Type}（不区分大小写）
                            ct_lower = comp_type.lower()
                            if comp_type and ct_lower in _tag_path_by_name:
                                cand = _tag_path_by_name[ct_lower]
                                if cand.startswith("Ship → Components →"):
                                    tags.add(cand)
                            # 尝试匹配 Size，通过 "Ship → Components → Sizes → Size{N}"
                            if comp_size >= 0:
                                size_key = f"Size{comp_size}"
                                if size_key in _tag_path_exact:
                                    sp = _tag_path_exact[size_key]
                                    if sp.startswith("Ship → Components →"):
                                        tags.add(sp)
                            # 尝试匹配 Grade，通过 "Ship → Components → Grade → {letter}"
                            if comp_grade >= 1 and comp_grade <= 5:
                                grade_letter = _grade_map.get(comp_grade, "")
                                if grade_letter and grade_letter in _tag_path_exact:
                                    gp = _tag_path_exact[grade_letter]
                                    if gp.startswith("Ship → Components →"):
                                        tags.add(gp)
                            break  # 只用第一个匹配的组件
            if tags:
                item_tags[uid] = {"n": item_name, "t": sorted(tags)}
    
    # 3. Archetype → 标签分组 (每组=一个可能出现的标签组合，组内ALL必须匹配)
    print("  构建 Archetype 索引...(按 entry 分组)")
    arch_entries = []
    for fpath in glob.glob(f"{ARCH_DIR}/**/*.json", recursive=True):
        data = load_json(fpath)
        if not data: continue
        rn = data.get("_RecordName_", short_name(fpath))
        rv = data.get("_RecordValue_", {})
        groups = []  # 每个 group = [tag_path, tag_path, ...]  组内必须ALL匹配
        group_weights = []
        group_stacks = []
        entry_names = set()
        
        # === V3 格式: 每个 entry 的 positiveTags 就是一个 group ===
        for e in rv.get("lootArchetype", {}).get("entries", []):
            en = e.get("name", "")
            if en: entry_names.add(en)
            sel = e.get("selector", {})
            if sel.get("_Type_") == "LootArchetypeV3Selector_Tags":
                grp = []
                for t in sel.get("tags", {}).get("positiveTags", []):
                    tid = get_uuid(t)
                    if tid and tid in tag_map: grp.append(tag_map[tid])
                if grp: 
                    groups.append(grp)
                    group_weights.append(e.get("weight", 1.0))
                    # V3 StackSize: ArchetypeOptionalDataV3_StackSize → stackSize.{min,max}
                    si = None
                    for od in e.get("optionalData", []):
                        if od.get("_Type_") == "ArchetypeOptionalDataV3_StackSize":
                            ss = od.get("stackSize", {})
                            mn = ss.get("min")
                            mx = ss.get("max")
                            if mn is not None and mx is not None:
                                si = {"min": mn, "max": mx}
                            break
                    group_stacks.append(si)
        
        # === V1 格式: Primary×Secondary 笛卡尔积 ===
        primary_entries = []  # [(tags, weight, stackInfo), ...]
        for e in rv.get("primaryOrGroup", {}).get("entries", []):
            en = e.get("name", "")
            if en: entry_names.add(en)
            uid = get_uuid(e.get("tag", {}))
            ptags = []
            if uid and uid in tag_map: ptags.append(tag_map[uid])
            for t in e.get("additionalTags", {}).get("positiveTags", []):
                uid2 = get_uuid(t)
                if uid2 and uid2 in tag_map: ptags.append(tag_map[uid2])
            pw = e.get("weight", 1.0)
            # V1/V2 StackSize: EntryOptionalData_StackSize → {min,max}
            si = None
            for od in e.get("optionalData", []):
                if od.get("_Type_") == "EntryOptionalData_StackSize":
                    mn = od.get("min")
                    mx = od.get("max")
                    if mn is not None and mx is not None:
                        si = {"min": mn, "max": mx}
                    break
            if ptags: primary_entries.append((ptags, pw, si))
        
        # secondary groups → list of [(tag, weight), ...]
        sec_groups = []  # [[(tag, weight), ...], ...]
        for sg in rv.get("secondaryOrGroups", []):
            sec_tags = []
            for e in sg.get("entries", []):
                uid = get_uuid(e.get("tag", {}))
                if uid and uid in tag_map:
                    sw = e.get("weight", 1.0)
                    sec_tags.append((tag_map[uid], sw))
            if sec_tags: sec_groups.append(sec_tags)
        
        # 笛卡尔积: primary × sec1 × sec2 × ... 带权重
        if primary_entries:
            def cartesian_w(lists):
                if not lists: return [([], 1.0, None)]
                result = []
                for first in lists[0]:
                    item, w = first[0], first[1]
                    si = first[2] if len(first) > 2 else None
                    for rest, rw, rsi in cartesian_w(lists[1:]):
                        if isinstance(item, list):
                            result.append((item + rest, w * rw, si or rsi))
                        else:
                            result.append(([item] + rest, w * rw, si or rsi))
                return result
            
            # Build list of weighted options
            primary_options = [(p, pw, si) for p, pw, si in primary_entries]
            sec_option_lists = []
            for sg in sec_groups:
                sec_option_lists.append([(t, w, None) for t, w in sg])
            
            all_options = [primary_options] + sec_option_lists
            combos = cartesian_w(all_options)
            for tags_list, combo_weight, si in combos:
                if tags_list: 
                    groups.append(tags_list)
                    group_weights.append(combo_weight)
                    group_stacks.append(si)
        elif sec_groups:
            # 只有 secondary 没有 primary 的情况
            for sc in cartesian(sec_groups):
                if sc: 
                    groups.append(sc)
                    group_stacks.append(None)
        
        if groups:
            arch_entries.append({
                "n": rn,
                "g": [sorted(g) for g in groups],
                "gw": group_weights,
                "gs": group_stacks,
                "e": sorted(entry_names) if entry_names else []
            })
    
    # 4. LootTable → Archetype
    # 4. LootTable → Archetype
    print("  构建 LootTable 索引...")
    tbl_file_to_name = {}
    tbl_list = []
    
    for root, dirs, files in os.walk(LOOT_DIR):
        for fname in files:
            if not fname.endswith(".json"): continue
            fpath = os.path.join(root, fname)
            data = load_json(fpath)
            if not data: continue
            rn = data.get("_RecordName_", short_name(fpath))
            tbl_file_to_name[short_name(fpath)] = rn
            rv = data.get("_RecordValue_", {})
            is_v3 = "LootTableV3" in rn
            arches = []
            aweights = []
            
            if is_v3:
                for entry in rv.get("lootTable", {}).get("lootArchetypes", []):
                    arch = entry.get("archetype", {})
                    w = entry.get("weight", 1.0)
                    if arch.get("_Type_") == "LootArchetypeV3_RecordRef":
                        ref = norm_path(arch.get("lootArchetypeRecord", ""), os.path.dirname(fpath))
                        if ref:
                            a_short = short_name(ref).lower()
                            for a in arch_entries:
                                an_lower = a["n"].lower()
                                if a_short in an_lower or an_lower.endswith(a_short):
                                    arches.append(a["n"]); aweights.append(w); break
            else:
                for entry in rv.get("lootArchetypes", []):
                    ref = norm_path(entry.get("archetype", ""), os.path.dirname(fpath))
                    w = entry.get("weight", 1.0)
                    if ref:
                        a_short = short_name(ref).lower()
                        for a in arch_entries:
                            an_lower = a["n"].lower()
                            if a_short in an_lower or an_lower.endswith(a_short):
                                arches.append(a["n"]); aweights.append(w); break
            
            tbl_list.append({"n": rn, "f": fname, "v3": is_v3, "a": arches, "aw": aweights})
    
    # 5. Slot Preset（含子目录如 contestedzones/）
    print("  解析区域容器配置...")
    slot_map = {}  # region -> [{"n": table_name, "w": weight, ...}]
    # 先扫根目录的 slotpreset — 解析 JSON 获取 lootTable + weight
    for fpath in glob.glob(f"{SLOT_DIR}/lootgeneration_slotpreset_*.json"):
        region = short_name(fpath).replace("lootgeneration_slotpreset_", "")
        data = load_json(fpath)
        if not data:
            continue
        rv = data.get("_RecordValue_", {})
        # 尝试从 multiConfig.taggedConfigs[].subConfig.subConfigManual.lootTable 提取
        mc = rv.get("multiConfig", {})
        tagged = mc.get("taggedConfigs", []) if isinstance(mc, dict) else []
        for tc in tagged:
            sc = tc.get("subConfig", {}) if isinstance(tc, dict) else {}
            if sc.get("subConfigManual"):
                manual = sc["subConfigManual"]
                lt = manual.get("lootTable", "")
                if lt:
                    lt_name = short_name(lt.replace("\\", "/")).replace(".json", "")
                    trn = tbl_file_to_name.get(lt_name, lt_name)
                    if region not in slot_map:
                        slot_map[region] = []
                    if not any(x.get("n") == trn for x in slot_map[region]):
                        slot_map[region].append({"n": trn, "w": 1.0})
        # 也扫描所有 loottable_ 引用（兼容旧格式）
        with open(fpath, "r", encoding="utf-8") as f:
            content = f.read()
        if region not in slot_map:
            slot_map[region] = []
        for m in re.finditer(r"(loottable_[a-z0-9_]+)\.json", content):
            trn = tbl_file_to_name.get(m.group(1), m.group(1))
            if not any(x.get("n") == trn for x in slot_map[region]):
                slot_map[region].append({"n": trn, "w": 1.0})
    # 再扫子目录下的区域文件（如 contestedzones/contestedzone_1a.json）
    for fpath in glob.glob(f"{SLOT_DIR}/**/*.json", recursive=True):
        region = short_name(os.path.dirname(fpath))
        fname = short_name(fpath)
        if fname.startswith("lootgeneration_slotpreset_"):
            continue
        if region == "slotpresets":
            continue
        # 解析 JSON 获取 lootTable 引用
        data = load_json(fpath)
        if data:
            rv = data.get("_RecordValue_", {})
            mc = rv.get("multiConfig", {})
            tagged = mc.get("taggedConfigs", []) if isinstance(mc, dict) else []
            for tc in tagged:
                sc = tc.get("subConfig", {}) if isinstance(tc, dict) else {}
                if sc.get("subConfigManual"):
                    manual = sc["subConfigManual"]
                    lt = manual.get("lootTable", "")
                    if lt:
                        lt_name = short_name(lt.replace("\\", "/")).replace(".json", "")
                        trn = tbl_file_to_name.get(lt_name, lt_name)
                        if region not in slot_map:
                            slot_map[region] = []
                        if not any(x.get("n") == trn for x in slot_map[region]):
                            slot_map[region].append({"n": trn, "w": 1.0})
        # 也扫描字符串引用（兼容）
        with open(fpath, "r", encoding="utf-8") as f:
            content = f.read()
        if region not in slot_map:
            slot_map[region] = []
        for m in re.finditer(r"(loottable_[a-z0-9_]+)\.json", content):
            trn = tbl_file_to_name.get(m.group(1), m.group(1))
            if not any(x.get("n") == trn for x in slot_map[region]):
                slot_map[region].append({"n": trn, "w": 1.0})
    slot_list = sorted([{"r": r, "c": sorted(c, key=lambda x: x["n"] if isinstance(x, dict) else x)} for r, c in slot_map.items() if c], key=lambda x: (x["r"] != "generic", x["r"]))
    
    # 6. V3 Slot Preset - 添加到 slot_map
    slot_map = add_v3_slot_data(db=None, slot_map=slot_map, item_tags=item_tags, RECORDS=RECORDS, load_json=load_json)
    # 重建 slot_list（含 V3 容器）
    slot_list = sorted([{"r": r, "c": sorted(c, key=lambda x: x["n"] if isinstance(x, dict) else x)} for r, c in slot_map.items() if c], key=lambda x: (x["r"] != "generic", x["r"]))
    
    # 7. NPC/尸体
    print("  扫描 NPC/尸体来源...")
    npc_list = []
    def _scan(comps, basedir):
        if not comps: return None
        for c in comps:
            if not c or not isinstance(c, dict): continue
            if "LootGenerationComponentParams" in c.get("_Type_", ""):
                ref = c.get("lootConfig", {}).get("lootTableV3", "") or c.get("lootConfig", {}).get("lootTable", "")
                if ref: return norm_path(ref, basedir)
            elif "SEntityLootableContainerParams" in c.get("_Type_", ""):
                ref = c.get("lootTableV3", "") or c.get("lootTable", "")
                if ref: return norm_path(ref, basedir)
        return None
    
    for root, dirs, files in os.walk(ACTOR_DIR):
        for fname in files:
            if not fname.endswith(".json"): continue
            data = load_json(os.path.join(root, fname))
            if not data: continue
            lt_path = _scan(data.get("_RecordValue_", {}).get("Components", []), os.path.join(root, fname))
            if lt_path:
                npc_list.append({
                    "n": data.get("_RecordName_", short_name(fname)),
                    "t": "NPC", "l": tbl_file_to_name.get(short_name(lt_path), short_name(lt_path))
                })
    if os.path.exists(MISSION_DIR):
        for fname in os.listdir(MISSION_DIR):
            if not fname.endswith(".json"): continue
            data = load_json(os.path.join(MISSION_DIR, fname))
            if not data: continue
            lt_path = _scan(data.get("_RecordValue_", {}).get("Components", []), MISSION_DIR)
            if lt_path:
                npc_list.append({
                    "n": data.get("_RecordName_", short_name(fname)),
                    "t": "容器", "l": tbl_file_to_name.get(short_name(lt_path), short_name(lt_path))
                })
    
    # 7b. 从 slot_registry.json 合并额外字段（chance/limit/fullness）
    sr_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "slot_registry.json")
    if os.path.exists(sr_path):
        try:
            with open(sr_path, "r", encoding="utf-8") as _f:
                _sr = json.load(_f)
            def _sr_key(n):
                # slot_registry 用 loottable_xxx (无 LootTable. 前缀，小写)
                return n.replace("LootTable.", "").lower()
            for _se in slot_list:
                _r = _se["r"]
                if _r not in _sr:
                    continue
                _src_map = {}
                for _sc in _sr[_r]:
                    _src_map[_sr_key(_sc["n"])] = _sc
                for _c in _se["c"]:
                    if isinstance(_c, dict):
                        _ck = _sr_key(_c["n"])
                        if _ck in _src_map:
                            _src = _src_map[_ck]
                            _c["chance"] = _src.get("init_prob", 1.0)
                            _c["fullness_min"] = _src.get("fullness_min", 0.0)
                            _c["fullness_max"] = _src.get("fullness_max", 0.5)
                            _c["limit"] = _src.get("limit", 0)
            print(f"  合并 slot_registry 完成")
        except Exception as _e:
            print(f"  合并 slot_registry 失败: {_e}")
    
    # 组装
    db = {
        "ver": VERSION, "tags": len(tag_map),
        "items": item_tags, "arches": arch_entries,
        "tables": tbl_list, "slots": slot_list, "npcs": npc_list
    }
    
    with open(DB_PATH, "w", encoding="utf-8") as f:
        json.dump(db, f, ensure_ascii=False, separators=(",", ":"))
    
    size_mb = os.path.getsize(DB_PATH) / 1024 / 1024
    print(f"  ✅ 已打包: {DB_PATH} ({size_mb:.1f} MB)")
    return db


