# ══════════════════════════════════════════════════════
# HTTP 服务
# ══════════════════════════════════════════════════════

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path = urlparse(self.path).path
        if path == "/" or path == "/index.html":
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            self.wfile.write(HTML.encode("utf-8"))
        elif path == "/data.json":
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            with open(DB_PATH, "rb") as f:
                self.wfile.write(f.read())
        elif path == "/names.json":
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            self.wfile.write(json.dumps(NAME_MAP_GLOBAL, ensure_ascii=False).encode("utf-8"))
        else:
            self.send_response(404)
            self.end_headers()
            self.wfile.write(b"404")
    
    def log_message(self, format, *args):
        pass  # 静默日志


def start_server(preferred_port=8080):
    import socket
    for port in range(preferred_port, preferred_port + 20):
        try:
            server = HTTPServer(("127.0.0.1", port), Handler)
            server.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            print(f"\n🌐 打开浏览器访问: http://127.0.0.1:{port}")
            if port != preferred_port:
                print(f"   (默认端口 {preferred_port} 被占用，已切换到 {port})")
            print("   按 Ctrl+C 或关闭此窗口停止服务")
            try:
                server.serve_forever()
            except KeyboardInterrupt:
                print("\n👋 服务已停止")
            return
        except (OSError, PermissionError):
            continue
    print(f"   ❌ 无法找到可用端口 ({preferred_port}~{preferred_port+19} 均被占用)")
    input("   按 Enter 键退出...")


# ══════════════════════════════════════════════════════
# 主入口
# ══════════════════════════════════════════════════════

def load_name_map():
    """从内嵌数据加载 item_Name 映射"""
    return _load_embedded_names()

def main():
    global HTML
    # 设置控制台窗口标题
    try:
        os.system("title 星际公民掉落查询工具 - 按 Ctrl+C 停止")
    except:
        pass
    print("=" * 50)
    print("  星际公民 物品掉落查询工具")
    print("=" * 50)
    
    # 使用内嵌数据库（若已有含 gs 的 loot_db.json 则跳过）
    if os.path.exists(DB_PATH):
        try:
            with open(DB_PATH, "r", encoding="utf-8") as f:
                _existing = json.load(f)
            if _existing.get("arches") and "gs" in _existing["arches"][0]:
                db = _existing
                print(f"\n📦 使用已有数据库 ({os.path.getsize(DB_PATH)/1024/1024:.1f} MB, 含堆叠数据)")
        except: pass
    if "db" not in locals():
        print("\n📦 解压内嵌数据库...")
        db = _load_embedded_db()
        # 排序区域：通用（generic）排最前
        db["slots"].sort(key=lambda s: (s["r"] != "generic", s["r"]))
        # 写一份到磁盘供 Web 服务使用
        with open(DB_PATH, "w", encoding="utf-8") as f:
            json.dump(db, f, ensure_ascii=False, separators=(",", ":"))
        size_mb = os.path.getsize(DB_PATH) / 1024 / 1024
        print(f"   解压完成 ({size_mb:.1f} MB)")
    
    # 加载名称映射并注入 HTML
    print("\n📋 加载物品名称映射...")
    name_map = load_name_map()
    global NAME_MAP_GLOBAL
    NAME_MAP_GLOBAL = name_map
    print(f"   名称映射加载完毕 ({len(name_map)} 条)")
    
    # 启动 Web 服务
    port = 8080
    print(f"\n🚀 启动本地服务...")
    
    # 延迟打开浏览器
    threading.Timer(1.5, lambda: webbrowser.open(f"http://127.0.0.1:{port}")).start()
    
    start_server(port)


if __name__ == "__main__":
    if "--rebuild" in sys.argv:
        print("📦 重建数据库（含堆叠数据）...")
        build_database()
        print("✅ 重建完成")
    main()
